<template><section class="config"><h2>事件跟踪配置</h2><el-alert v-if="error" :title="error" type="error"/><el-tabs><el-tab-pane label="菜单规则"><el-table :data="rules"><el-table-column prop="menu_key" label="页面路径"/><el-table-column prop="enabled" label="启用"/><el-table-column prop="default_due_hours" label="默认期限（小时）"/><el-table-column label="操作"><template #default="{row}"><el-button @click="editRule(row)">编辑</el-button><el-button @click="remove('rules',row.id)">删除</el-button></template></el-table-column></el-table><el-button @click="editRule()">新增菜单规则</el-button><el-form label-position="top"><el-form-item label="菜单页面路径"><el-select v-model="rule.menu_key" filterable><el-option v-for="m in menus" :key="m.path" :label="m.label+' '+m.path" :value="m.path"/></el-select></el-form-item><el-form-item label="发起层级"><el-select v-model="rule.scope"><el-option label="页面" value="page"/><el-option label="单据" value="record"/><el-option label="页面和单据" value="both"/></el-select></el-form-item><el-checkbox v-model="rule.enabled">启用悬浮跟踪</el-checkbox><el-checkbox v-model="rule.screenshot_enabled">允许截图</el-checkbox><el-form-item label="默认处理人"><el-select v-model="rule.default_assignee" clearable><el-option v-for="u in candidates.users" :key="u.id" :value="u.id" :label="u.full_name||u.username"/></el-select></el-form-item><el-form-item label="候选部门"><el-select v-model="rule.candidate_departments" multiple><el-option v-for="d in candidates.departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="默认办理期限（小时）"><el-input-number v-model="rule.default_due_hours" :min="1"/></el-form-item><el-form-item label="催办间隔（分钟）"><el-input-number v-model="rule.reminder_interval_minutes" :min="1"/></el-form-item><el-button type="primary" @click="save('rules',rule)">保存菜单规则</el-button></el-form></el-tab-pane>
<el-tab-pane label="部门管辖授权"><el-table :data="grants"><el-table-column prop="user" label="用户ID"/><el-table-column prop="department" label="部门ID"/><el-table-column prop="permissions" label="权限"/><el-table-column label="操作"><template #default="{row}"><el-button @click="editGrant(row)">编辑</el-button><el-button @click="remove('grants',row.id)">撤销</el-button></template></el-table-column></el-table><el-button @click="editGrant()">新增管辖授权</el-button><el-form label-position="top"><el-form-item label="管辖人"><el-select v-model="grant.user" filterable><el-option v-for="u in candidates.users" :key="u.id" :value="u.id" :label="u.full_name||u.username"/></el-select></el-form-item><el-form-item label="管辖部门"><el-select v-model="grant.departments" multiple :disabled="Boolean(grant.id)"><el-option v-for="d in candidates.departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-checkbox v-model="grant.include_descendants">包含下级部门</el-checkbox><el-form-item label="操作权限"><el-checkbox-group v-model="grant.permissions"><el-checkbox v-for="(label,key) in permissions" :key="key" :label="label" :value="key"/></el-checkbox-group></el-form-item><el-form-item label="生效时间（留空立即生效）"><el-date-picker v-model="grant.starts_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="结束时间（留空长期）"><el-date-picker v-model="grant.ends_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-button type="primary" @click="save('grants',grant)">保存管辖授权</el-button></el-form></el-tab-pane></el-tabs></section></template>
<script setup>
import {ref,reactive,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {tracking,rows} from '../../api/issueTracking';import {menuItems,flattenMenuItems} from '../../router/menu';
const menus=flattenMenuItems(menuItems),candidates=ref({users:[],departments:[]}),rules=ref([]),grants=ref([]),error=ref('');const permissions={view:'查看',remind:'催办',reassign:'改派',reschedule:'改期',close:'关闭',reopen:'重开',transfer:'部门移交',return:'退回办理'};
const rule=reactive({}),grant=reactive({});function reset(obj,data){Object.keys(obj).forEach(k=>delete obj[k]);Object.assign(obj,data);}function editRule(row){reset(rule,row?{...row,candidate_departments:[...row.candidate_departments]}:{menu_key:'',scope:'both',enabled:true,screenshot_enabled:true,default_assignee:null,candidate_departments:[],default_due_hours:24,reminder_interval_minutes:60});}function editGrant(row){reset(grant,row?{...row,departments:[row.department],permissions:[...row.permissions]}:{user:null,departments:[],include_descendants:false,permissions:['view','remind','reassign'],starts_at:null,ends_at:null});}
async function load(){try{candidates.value=await tracking('candidates/');rules.value=rows(await tracking('rules/'));grants.value=rows(await tracking('grants/'));}catch(e){error.value=e.message;}}
async function save(kind,data){error.value='';try{if(kind==='grants'){
if(!data.departments?.length)throw new Error('请选择至少一个管辖部门');
while(data.departments.length){const department=data.departments[0];const {departments,...payload}=data;await tracking(`${kind}/${data.id?data.id+'/':''}`,data.id?'patch':'post',{...payload,department});if(data.id)break;data.departments.shift();}
}else await tracking(`${kind}/${data.id?data.id+'/':''}`,data.id?'patch':'post',data);ElMessage.success('配置已保存');await load();}catch(e){error.value=e.message;}}
async function remove(kind,id){try{await ElMessageBox.confirm('确认撤销此配置？','确认');await tracking(`${kind}/${id}/`,'delete');await load();}catch(e){if(e?.message)error.value=e.message;}}
onMounted(()=>{editRule();editGrant();load();});
</script><style scoped>.config{padding:20px;background:white}.el-form{max-width:650px;margin-top:20px}.el-select{width:100%}</style>
